"use strict";
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const assert = require("node:assert/strict");
const crypto = require("node:crypto");
const { spawnSync } = require("node:child_process");
const root = path.resolve(__dirname, "../../..");
const git = "C:/Program Files/Git/cmd/git.exe";
const hash = bytes => crypto.createHash("sha256").update(bytes).digest("hex");
const read = p => fs.readFileSync(path.join(root, p));
const json = p => JSON.parse(read(p));
function command(exe, args, cwd) {
  const start = Date.now();
  const p = spawnSync(exe, args, {cwd, encoding:"utf8", maxBuffer:64*1024*1024, shell:false});
  return {exitCode:p.status, durationMs:Date.now()-start, stdout:p.stdout||"", stderr:p.stderr||""};
}
const revision = command(git, ["rev-parse", "HEAD"], root).stdout.trim();
assert(revision.startsWith("fda9a33"));
assert.equal(command(git, ["status", "--porcelain"], root).stdout, "");
const approved = json("architecture/migration/stage_3_approved_batches.json");
const state = json("architecture/migration/stage_3_execution_state.json");
assert.equal(state.releaseVersion,"0.24.43");
assert.equal(json("package.json").version,state.releaseVersion);
assert.deepEqual(state.completedBatchIds, approved.batches.slice(0,6).map(x=>x.id));
assert.equal(state.activeBatchId,approved.batches[6].id);
assert.equal(state.activeBatchPhase,"runtime-active");
assert.equal(state.compatibilityRuntimeActivated,true);
const tracked = command(git,["ls-files","-z"],root).stdout.split("\0").filter(Boolean);
const sourceHashes = Object.fromEntries(tracked.map(p=>[p,hash(read(p))]));
const temp = fs.mkdtempSync(path.join(os.tmpdir(),"cyber-fishing-3-7-8-"));
assert.equal(path.dirname(temp),path.resolve(os.tmpdir()));
const result = {sourceCommit:revision,repositoryClean:true,startedAt:new Date().toISOString(),temporaryRoot:temp,nodeVersion:process.version,sourceSnapshotSha256:hash(JSON.stringify(sourceHashes)),lifecycle:state,commands:{},status:"running"};
function save(){ fs.writeFileSync(path.join(__dirname,"result.json"),JSON.stringify(result,null,2)+"\n"); }
function run(label,exe,args,cwd){
  console.log(`START ${label}`);
  const record = command(exe,args,cwd);
  fs.writeFileSync(path.join(__dirname,label+".log"),record.stdout+record.stderr);
  const counts = record.stdout.match(/Passed (\d+) checks in ([\d.]+)s\./);
  result.commands[label] = {command:[exe,...args],exitCode:record.exitCode,durationMs:record.durationMs,logSha256:hash(record.stdout+record.stderr),...(counts?{passedChecks:Number(counts[1]),failedChecks:0}:{}),tail:(record.stdout+record.stderr).slice(-1500)};
  save();
  console.log(`END ${label}: ${record.exitCode}\n${result.commands[label].tail}`);
  assert.equal(record.exitCode,0,`${label} failed; see ${label}.log`);
}
try {
  for(const p of tracked){ const target=path.join(temp,p);fs.mkdirSync(path.dirname(target),{recursive:true});fs.copyFileSync(path.join(root,p),target); }
  for(const [p,sha] of Object.entries(sourceHashes)) assert.equal(hash(fs.readFileSync(path.join(temp,p))),sha);
  assert.equal(fs.existsSync(path.join(temp,"node_modules")),false);
  assert.equal(fs.existsSync(path.join(temp,"dist")),false);
  const npmCmd=command("where.exe",["npm.cmd"],root).stdout.trim().split(/\r?\n/)[0];
  const npmCli=path.join(path.dirname(npmCmd),"node_modules/npm/bin/npm-cli.js");
  const npmVersion=command(process.execPath,[npmCli,"--version"],temp).stdout.trim();
  assert.equal("npm@"+npmVersion,json("package.json").packageManager);
  result.npmVersion=npmVersion;
  save();
  run("npm-ci",process.execPath,[npmCli,"ci","--no-audit","--no-fund"],temp);
  assert.equal(hash(fs.readFileSync(path.join(temp,"package-lock.json"))),sourceHashes["package-lock.json"]);
  for(const suite of ["architecture","quick","all"]) run(suite,process.execPath,["utils/run-checks.js","--suite",suite],temp);
  run("generated-build",process.execPath,["utils/build/build_stage_3_compat_runtime.js"],temp);
  run("live-identity",process.execPath,["utils/architecture/stage-3-batch-007-live-runtime-integration-check.js"],temp);
  run("reconciliation",process.execPath,["utils/architecture/finalize-stage-3-batch-007-observations.js","--acceptance-gate"],temp);
  for(const [p,sha] of Object.entries(sourceHashes)){
    assert.equal(hash(read(p)),sha,`source changed: ${p}`);
    assert.equal(hash(fs.readFileSync(path.join(temp,p))),sha,`fresh source changed: ${p}`);
  }
  const bundle="dist/stage-3-compat-runtime/compat_runtime.iife.js";
  result.generatedRuntimeSha256=hash(fs.readFileSync(path.join(temp,bundle)));
  assert.equal(result.generatedRuntimeSha256,hash(read(bundle)));
  assert.equal(command(git,["status","--porcelain"],root).stdout,"");
  result.protectedBytesUnchanged=true;
  result.lockfileUnchanged=true;
  result.status="fresh-suites-and-generated-runtime-passed";
} catch(error) {result.status="failed";result.error=error.stack;process.exitCode=1;console.error(error.stack);}
finally {result.finishedAt=new Date().toISOString();save();console.log(JSON.stringify({status:result.status,temporaryRoot:temp}));}

