const fs=require('node:fs');
const path=require('node:path');
const root=JSON.parse(fs.readFileSync(path.join(__dirname,'result.json'))).temporaryRoot;
const template=fs.readFileSync(path.join(__dirname,'browser-probe.html'),'utf8');
const probe=template.slice(template.indexOf('<style>'));
const index=fs.readFileSync(path.join(root,'index.html'),'utf8');
fs.writeFileSync(path.join(root,'browser-probe.html'),index.replace('</body>',probe+'\n</body>'));
console.log('Test-only page: unchanged index script sequence plus diagnostic report; original index unchanged.');
